"""
Project-wide utility helpers.

This module centralizes common string, path, and IO operations
used across the codebase. Keep additions focused and well-tested.
"""
import os, sys, json, hashlib, logging, subprocess, tempfile
from pathlib import Path
from typing import Optional, List, Dict, Any
from functools import lru_cache

log = logging.getLogger(__name__)


def read_json(path: Path) -> Dict[str, Any]:
    """Load JSON with graceful fallback."""
    try:
        return json.loads(path.read_text())
    except Exception as e:
        log.warning(f"Failed reading {path}: {e}")
        return {}


def write_json(path: Path, data: Dict[str, Any], indent: int = 2) -> bool:
    """Atomic JSON write via temp file."""
    try:
        with tempfile.NamedTemporaryFile('w', dir=path.parent, delete=False) as tf:
            json.dump(data, tf, indent=indent)
            tf.flush()
            os.fsync(tf.fileno())
        os.replace(tf.name, path)
        return True
    except Exception as e:
        log.error(f"Write failed {path}: {e}")
        return False


def sha256sum(path: Path) -> str:
    """Streaming SHA-256 for large files."""
    h = hashlib.sha256()
    with path.open('rb') as f:
        for chunk in iter(lambda: f.read(8192), b''):
            h.update(chunk)
    return h.hexdigest()


def find_project_root(start: Optional[Path] = None) -> Path:
    """Walk up to locate .git or pyproject.toml."""
    cur = (start or Path.cwd()).resolve()
    for p in [cur, *cur.parents]:
        if (p / '.git').exists() or (p / 'pyproject.toml').exists():
            return p
    return cur


def sanitize_filename(name: str, max_len: int = 200) -> str:
    """Strip problematic chars, preserve unicode."""
    return re.sub(r'[<>:"|?*\x00-\x1f]', '_', name)[:max_len]


